(837, 1, '2025-05-30 15:27:35', '2025-05-30 18:27:35', '<!-- wp:acf/hero {\"name\":\"acf/hero\",\"data\":{\"title\":\"\\u003cp style=\\u0022text-align: center;\\u0022\\u003e\\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eRevolucionando Economias Digitais com\\u003c/span\\u003e\\r\\n\\u003cstrong\\u003e\\u003cspan style=\\u0022color: #ffc700;\\u0022\\u003eLiberdade\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003ee\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffc700;\\u0022\\u003eTecnologia\\u003c/span\\u003e\\u003c/strong\\u003e\\u003c/p\\u003e\",\"_title\":\"field_67eab79013319\",\"text\":\"\\u003cp style=\\u0022text-align: center;\\u0022\\u003e\\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eNa BDM Digital, unimos a inovação da\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffc700;\\u0022\\u003eblockchain própria\\u003c/span\\u003e\\r\\n\\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eà missão de empoderar\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffc700;\\u0022\\u003epessoas\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003ee\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffc700;\\u0022\\u003enegócios\\u003c/span\\u003e\\u003c/p\\u003e\",\"_text\":\"field_67eab79b1331a\",\"backgroundimage\":352,\"_backgroundimage\":\"field_67eab80613320\",\"media\":\"\",\"_media\":\"field_67eab81c13321\",\"btnLabel\":\"Comece Agora\",\"_btnLabel\":\"field_67eab7bf1331c\",\"btnClass\":\"\\u002d\\u002dprimary uppercase px-12\",\"_btnClass\":\"field_67eab7d51331d\",\"url\":\"#\",\"_url\":\"field_67eab7e41331e\",\"btnAnimation\":\"tada\",\"_btnAnimation\":\"field_67eab7eb1331f\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:acf/section {\"name\":\"acf/section\",\"data\":{\"helper\":\"\",\"_helper\":\"field_67fffe01d797e\",\"title\":\"\\u003cp style=\\u0022text-align: center;\\u0022\\u003e\\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eUma\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffc700;\\u0022\\u003e\\u003cstrong\\u003eNova Era\\u003c/strong\\u003e\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003ede Prosperidade Compartilhada\\u003c/span\\u003e\\u003c/p\\u003e\",\"_title\":\"field_67ec239c36e58\",\"subtitle\":\"\",\"_subtitle\":\"field_67ec257c36e64\",\"text\":\"\\u003cp style=\\u0022text-align: center;\\u0022\\u003e\\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eO Metaverso e as criptomoedas estão redefinindo como negociamos, criamos e nos conectamos. Na \\u003cstrong\\u003eBDM Digital\\u003c/strong\\u003e, desenvolvemos a primeira\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffc700;\\u0022\\u003eblockchain brasileira\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003ecom validação em segundos, \\u003c/span\\u003e\\r\\n\\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eusando um \\u003cstrong\\u003eProof-of-Stake aprimorado\\u003c/strong\\u003e, para garantir transações rápidas e seguras.\\u003c/span\\u003e\\u003c/p\\u003e\\r\\n\\u003cp style=\\u0022text-align: center;\\u0022\\u003e\\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eCombinada\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eà\\u003c/span\\u003e \\u003cspan style=\\u0022color: #ffc700;\\u0022\\u003e\\u003cstrong\\u003eDourado.cash\\u003c/strong\\u003e\\u003c/span\\u003e, \\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003enossa plataforma de pagamentos, oferecemos uma ponte entre o mundo físico e o digital, onde todos podem usufruir de liberdade financeira, seja em moeda social (BDM) \\u003c/span\\u003e\\r\\n\\u003cspan style=\\u0022color: #ffffff;\\u0022\\u003eou em criptoativos globais.\\u003c/span\\u003e\\u003c/p\\u003e\",\"_text\":\"field_67ec23ab36e59\",\"backgroundimage\":355,\"_backgroundimage\":\"field_67ec23f136e5a\",\"background\":\"\",\"_background\":\"field_67ec23ff36e5b\",\"backgroundcolor\":\"\",\"_backgroundcolor\":\"field_67ec244b36e5c\",\"backgroundsize\":\"cover\",\"_backgr